@mcp.tool()
def book_slot(slot_id: str, requested_by: str, correlation_id: str) -> str:
    if correlation_id in seen_requests:
        return seen_requests[correlation_id]   # same reply, no repeated action
    with slot_lock(slot_id):
        result = "already booked" if is_taken(slot_id) else "booked"
        if result == "booked":
            mark_taken(slot_id, requested_by)
        seen_requests[correlation_id] = result
        return result

